template:
module top_module(input a, b, output out);
  // assign out = a & b;
endmodule

testbench:
`timescale 1ns/1ps
module tb();
    reg a, b;
    wire out;
    integer passed_tests = 0;
    integer total_tests = 0;

    top_module dut (.a(a), .b(b), .out(out));

    initial begin
        $display("Testing AND gate...");

        // Test 1
        a=0; b=0; #10;
        total_tests = total_tests + 1;
        if (out !== 1'b0) begin
            $display("FAIL 00: Expected out=0, Got out=%b", out);
        end else begin
            passed_tests = passed_tests + 1;
        end

        // Test 2
        a=0; b=1; #10;
        total_tests = total_tests + 1;
        if (out !== 1'b0) begin
            $display("FAIL 01: Expected out=0, Got out=%b", out);
        end else begin
            passed_tests = passed_tests + 1;
        end

        // Test 3
        a=1; b=0; #10;
        total_tests = total_tests + 1;
        if (out !== 1'b0) begin
            $display("FAIL 10: Expected out=0, Got out=%b", out);
        end else begin
            passed_tests = passed_tests + 1;
        end

        // Test 4
        a=1; b=1; #10;
        total_tests = total_tests + 1;
        if (out !== 1'b1) begin
            $display("FAIL 11: Expected out=1, Got out=%b", out);
        end else begin
            passed_tests = passed_tests + 1;
        end

        // Final Result
        if (passed_tests == total_tests) begin
            $display("PASS: All %0d tests correct!", total_tests);
        end else begin
            $display("FAIL: Passed %0d/%0d tests", passed_tests, total_tests);
        end
        $finish;
    end
endmodule

