template:
module top_module(input clk, input d, output reg q);
  // always @(posedge clk) q <= d;
endmodule

testbench:
`timescale 1ns/1ps
module tb();
    reg clk=0, d;
    wire q;
    integer passed_tests = 0;
    integer total_tests = 0;

    top_module dut (.clk(clk), .d(d), .q(q));

    // Clock generator
    always #5 clk = ~clk;

    initial begin
        $display("Testing D Flip-Flop...");

        // Test 1
        d=0; #10; // Wait for first posedge
        total_tests = total_tests + 1;
        if (q !== 1'b0) begin
            $display("FAIL: After 1st posedge, q should be 0, got %b", q);
        end else begin
            passed_tests = passed_tests + 1;
        end

        // Test 2
        d=1; #10; // Wait for second posedge
        total_tests = total_tests + 1;
        if (q !== 1'b1) begin
            $display("FAIL: After 2nd posedge, q should be 1, got %b", q);
        end else begin
            passed_tests = passed_tests + 1;
        end

        // Test 3
        d=0; #10; // Wait for third posedge
        total_tests = total_tests + 1;
        if (q !== 1'b0) begin
            $display("FAIL: After 3rd posedge, q should be 0, got %b", q);
        end else begin
            passed_tests = passed_tests + 1;
        end

        // Test 4
        d=1; #10; // Wait for fourth posedge
        total_tests = total_tests + 1;
        if (q !== 1'b1) begin
            $display("FAIL: After 4th posedge, q should be 1, got %b", q);
        end else begin
            passed_tests = passed_tests + 1;
        end

        // Final Result
        if (passed_tests == total_tests) begin
            $display("PASS: All %0d tests correct!", total_tests);
        end else begin
            $display("FAIL: Passed %0d/%0d tests", passed_tests, total_tests);
        end
        $finish;
    end
endmodule
